-- 052_commulingo_nkvd_subordinates.sql
-- Adds the subordinates of the three NKVD chiefs already in the dictionary
-- (yagoda, yezhov, beria). Three cohorts, plus the Georgian apparatus:
--   * Yagoda's OGPU/NKVD department heads and regional barons
--   * The Gulag and canal administrators
--   * Beria's Transcaucasian clients, incl. the December 1953 trial group
--   * The Georgian security officials tried at Tbilisi in September 1955
--
-- Framing note: the cohorts are patronage networks, not fates. Only Molchanov,
-- Pauker and Prokofiev fell *with* Yagoda; Balitsky, Berman and Deribas
-- outlasted him and were purged later by Yezhov. Evdokimov left the organs for
-- party work in Jan 1934, was hostile to Yagoda, and rose under Yezhov because
-- of it. Each bio states the man's own trajectory rather than his patron's.
--
-- Sourcing: Petrov & Skorkin, "Kto rukovodil NKVD 1934-1941"; Petrov, "Kto
-- rukovodil organami gosbezopasnosti 1941-1954"; RGASPI indictment texts
-- (f.17 op.171 dd.474/476) via istmat; Memorial execution-list data.
-- Contested claims are omitted rather than asserted. Specifically excluded:
-- Blokhin's cause of death (suicide vs. heart attack, both in the record) and
-- his apron/gauntlets (one 1991 deposition); Pauker's Orlov-memoir anecdotes;
-- Nadaraya's custodial testimony about Beria's sexual crimes; Tsanava's
-- "suicide" (medical record gives cardiac failure); Molchanov's rehabilitation
-- (three sources, three answers). `moment` is left empty throughout: no
-- attributable quotation survives for these men that is not memoir-derived.
--
-- Idempotent: ON CONFLICT updates content but preserves existing sort_order.
--
-- DO NOT REPLAY THIS ON A LIVE DB. It was applied once, on 2026-07-15. People
-- are normally edited through the admin UI (data/commulingo/people-admin-store.js),
-- and the ON CONFLICT DO UPDATE above would silently overwrite any later edit to
-- these 32 rows with the prose below. It is committed as the textual record of
-- this content and of the sourcing decisions above, not as a replayable step.
-- If you need it in a fresh environment, check first that these ids are absent.

INSERT INTO commulingo_people
    (id, group_id, sort_order, initial, cyrillic, years_label, birth_year, death_year,
     name_ko, name_en, epithet_ko, epithet_en, moment_ko, moment_en, bio_ko, bio_en,
     fate_kind, fate_label_ko, fate_label_en,
     citizenship_code, citizenship_label_ko, citizenship_label_en,
     origin_code, origin_label_ko, origin_label_en, updated_at)
SELECT v.id, 'stalin-era',
       (SELECT COALESCE(MAX(sort_order), -1) FROM commulingo_people) + v.ord,
       v.initial, v.cyrillic, v.years_label, v.birth_year, v.death_year,
       v.name_ko, v.name_en, v.epithet_ko, v.epithet_en, '', '', v.bio_ko, v.bio_en,
       v.fate_kind, v.fate_label_ko, v.fate_label_en,
       'soviet', '소련', 'Soviet Union',
       v.origin_code, v.origin_label_ko, v.origin_label_en, NOW()
FROM (VALUES

-- ---------------------------------------------------------------- Yagoda's men
('molchanov', 1, 'Г', 'Георгий Молчанов', '1897–1937', 1897, 1937,
 '게오르기 몰차노프', 'Georgy Molchanov',
 '야고다의 비밀정치국장', 'Yagoda''s chief of the Secret Political Department',
 $q$1920년 체카에 들어가 그로즈니 체카 의장과 이바노보-보즈네센스크 GPU 책임자를 지내며 집단화기의 탄압을 조직했다. 1931년 11월 야고다는 그를 비밀정치국(SPO) 국장에 앉혔다. 반대파와 성직자, 인텔리겐치아, 농민을 감시하고 탄압하는 기관으로, 야고다 체제의 정치경찰 기능 그 자체였다. 1932년 류틴 그룹 체포를 지휘했고, 1934년 키로프 암살 뒤의 대량 체포('키로프 물결')를 운영했으며, 1935년 크렘린 사건과 1936년 8월 지노비예프-카메네프 재판의 수사 실무를 맡았다. 그의 자리는 전적으로 야고다의 후원에 달려 있었다. 1936년 9월 예조프가 야고다를 대체하자 SPO에서 밀려나 벨로루시 NKVD로 좌천됐고, 예조프가 야고다의 기구를 숙청할 때 가장 먼저 체포된 고위 간부 중 하나가 되어 1937년 10월 총살됐다.$q$,
 $q$Molchanov entered the Cheka in 1920 and rose through provincial security work, chairing the Grozny Cheka and running the Ivanovo-Voznesensk GPU, where he organized repression during forced collectivization. In November 1931 Yagoda made him chief of the Secret Political Department, the branch responsible for surveillance and repression of former oppositionists, clergy, intelligentsia and the peasantry. He was thus the operational manager of Yagoda's core political-police function: he directed the 1932 arrests of the Ryutin group, ran the mass arrests of the "Kirov stream" after December 1934, and handled the investigative preparation of the 1935 Kremlin Case and the August 1936 Zinoviev-Kamenev trial. His position depended entirely on Yagoda's patronage. When Yezhov took over in September 1936 he was pushed out to the Belorussian NKVD, then became one of the first senior officers arrested in the purge of Yagoda's apparatus. He was shot in October 1937.$q$,
 'executed', '처형', 'Executed', 'ukraine', '우크라이나', 'Ukraine'),

('pauker', 2, 'К', 'Карл Паукер', '1893–1937', 1893, 1937,
 '카를 파우케르', 'Karl Pauker',
 '스탈린의 경호를 맡은 작전국장', 'The operations chief who guarded Stalin',
 $q$렘베르크(현 리비우)의 유대인 이발사이자 극장 분장사 출신으로, 1914년 오스트리아-헝가리군에 징집됐다가 1915년 러시아군에 포로로 잡혔다. 투르케스탄 포로수용소에서 급진화되어 1917년 볼셰비키에 가담했고 1918년 사마르칸트에서 체카에 들어갔다. 1923년부터 OGPU 작전국(Operod) 국장으로 체포와 수색, 감시, 처형, 크렘린 경비를 관장했으며, 1924년부터는 스탈린의 개인 경호를 직접 책임져 그에게 상시로 접근할 수 있는 몇 안 되는 인물이 되었다. 야고다 아래에서 그의 작전국은 1930년대 정치사건의 물리적 기구를 공급했고, 1936년 8월 재판 뒤의 처형을 집행했다. 개인적 근접성은 그를 지켜 주지 못했다. 1937년 4월 당에서 제명·해임되고 며칠 뒤 스탈린 암살 모의 혐의로 체포되어 8월 총살됐으며, 복권되지 않았다.$q$,
 $q$A Galician Jew from Lemberg with four years of schooling, Pauker worked as a theatrical hairdresser and make-up artist before conscription into the Austro-Hungarian army in 1914. Captured in 1915, he was radicalized in a Turkestan POW camp, joined the Bolsheviks in 1917 and entered the Cheka at Samarkand in 1918. By 1923 he headed the OGPU Operations Department, which controlled arrests, searches, surveillance, executions and Kremlin guard duty. From 1924 he personally ran Stalin's bodyguard, becoming a fixture of the household and one of the few men with constant physical access to him. Under Yagoda his department supplied the arresting officers and physical machinery for the political cases of the early 1930s, and administered the executions following the August 1936 trial. Proximity did not protect him: expelled from the party and dismissed in April 1937, he was arrested days later on a charge of preparing an attempt on Stalin's life and shot that August. He has never been rehabilitated.$q$,
 'executed', '처형', 'Executed', 'ukraine', '우크라이나', 'Ukraine'),

('matvei-berman', 3, 'М', 'Матвей Берман', '1898–1939', 1898, 1939,
 '마트베이 베르만', 'Matvei Berman',
 '굴라크를 확장한 최장수 수장', 'The longest-serving chief who built up the Gulag',
 $q$스무 살이던 1918년 체카에 들어가 글라조프 지구 체카 의장을 지냈고, 시베리아와 중앙아시아를 거치며 부랴트-몽골 자치공화국 내무인민위원과 우즈베크 GPU 의장을 역임했다. 1930년 신설된 굴라크의 부책임자가 되었고, 1932년 6월부터 1937년 8월까지 굴라크를 이끌었다. 초기 수장 가운데 최장수였으며 야고다의 NKVD 재임 기간 전체에 걸쳐 수용소 체계를 운영한 인물이다. 그의 아래에서 굴라크는 교정노동 실험에서 소비에트 경제의 핵심 도구로 확장됐다. 1933년 완공된 백해-발트 운하와 이어 모스크바-볼가 운하를 죄수 노동으로 건설했고, 강제노동을 공개적으로 정당화한 '개조'(perekovka) 교리를 선전했다. 그의 몰락은 야고다와 함께 오지 않았다. 1937년 8월 체신인민위원으로 옮겨졌고, 예조프의 측근들이 무너지던 1938년 12월 말렌코프의 집무실에서 체포되어 1939년 3월 총살됐다. 1957년 복권됐다.$q$,
 $q$Berman joined the Cheka in 1918 at twenty and chaired the Glazov district Cheka, then moved through Siberian and Central Asian posts, serving as internal affairs commissar of the Buryat-Mongolian ASSR and chairman of the Uzbek GPU. In 1930 he became deputy chief of the newly created Gulag, and from June 1932 to August 1937 he headed it, the longest-serving of its early chiefs and the man who ran the camp system throughout Yagoda's tenure. Under him the Gulag expanded from a corrective-labour experiment into a central instrument of the Soviet economy: he oversaw the prisoner-built White Sea-Baltic Canal, completed in 1933, and then the Moscow-Volga Canal, and promoted the doctrine of "reforging" that publicly justified forced labour. His fall came later than Yagoda's. In August 1937 he was moved to People's Commissar of Communications, a standard prelude to arrest, and was taken in December 1938 in Malenkov's office as Yezhov's own circle collapsed. He was shot in March 1939 and rehabilitated in 1957.$q$,
 'executed', '처형', 'Executed', 'russia', '러시아', 'Russia'),

('balitsky', 4, 'В', 'Всеволод Балицкий', '1892–1937', 1892, 1937,
 '프세볼로트 발리츠키', 'Vsevolod Balitsky',
 '우크라이나 보안기구의 지배자', 'The master of the Ukrainian security apparatus',
 $q$경력을 거의 전부 우크라이나에서 쌓았다. 1918년 12월 전우크라이나 체카 콜레기움에 들어가 볼히니아와 키예프 체카를 이끌었고, 1923년부터 십사 년 대부분을 우크라이나 GPU 수장으로 보내며 공화국 보안의 지배적 인물이자 동시에 내무인민위원이었다. 1932년 11월 곡물 조달을 무조건 관철하라는 지시와 함께 OGPU 전권대표로 우크라이나에 파견되어 홀로도모르 기간의 보안기구를 지휘했고, 1933년 3월 정치국은 그를 포함한 트로이카에 봉기·반혁명 사건을 사형으로 처결할 권한을 주었다. '우크라이나 군사조직'(UVO) 사건을 비롯한 민족주의 조작 사건들을 운영했고, 키로프 암살 뒤 우크라이나의 대량 체포와 추방을 감독했다. 1935년 국가보안위원 1급에 올랐으나 야고다의 몰락을 일 년도 넘기지 못했다. 1937년 5월 극동으로 전출되었고 7월 예조프의 영장으로 체포되어 11월 총살됐다. 러시아 법원은 1998년 복권을 거부했다.$q$,
 $q$Balitsky built his career almost entirely in Ukraine, entering the All-Ukrainian Cheka collegium in December 1918 and chairing the Volhynia and Kyiv Chekas before heading the Ukrainian GPU from 1923, a post he held for most of the next fourteen years. He was the dominant security figure in the republic and simultaneously its internal affairs commissar. Sent back as OGPU plenipotentiary in November 1932 with instructions to enforce grain procurement unconditionally, he directed the security apparatus during the Holodomor, and in March 1933 the Politburo empowered a troika including him to try insurrection and counter-revolution cases with capital authority. He ran the fabricated Ukrainian nationalist cases of the period, including the "Ukrainian Military Organisation" affair, and after Kirov's murder oversaw mass arrests and deportations. Promoted to Commissar of State Security 1st Rank in 1935, he survived Yagoda's fall by less than a year: transferred to the Far East in May 1937, arrested in July on Yezhov's warrant, and shot in November. Russian courts refused him rehabilitation in 1998.$q$,
 'executed', '처형', 'Executed', 'ukraine', '우크라이나', 'Ukraine'),

('georgy-prokofiev', 5, 'Г', 'Георгий Прокофьев', '1895–1937', 1895, 1937,
 '게오르기 프로코피예프', 'Georgy Prokofiev',
 '경제 파괴 사건을 만들어 낸 부인민위원', 'The deputy commissar who manufactured the wrecking cases',
 $q$키예프 출신 체키스트로 OGPU 비밀국과 정보국을 거쳐 1926년 2월 경제국(EKU) 국장이 되어 1931년까지 이끌었다. 경제 방첩을 담당한 이 부서는 그의 지휘 아래 소비에트 기술 전문가들을 겨눈 대규모 '파괴 공작' 사건들을 만들어 냈고, 산업의 실패를 범죄로 바꾸어 놓았다. 1932년 11월 OGPU 부의장이 되면서 동시에 보안기관에 갓 예속된 일반 경찰, 곧 민병대(GURKM)를 관장했다. 통상적 치안을 체키스트의 통제 아래 두는 통합이었다. 1934년 7월 NKVD가 창설되자 야고다의 제2부인민위원으로서 신설 인민위원부 최상층의 소수 집단에 들었고, 1935년 국가보안위원 1급을 받았다. 야고다의 측근들과 함께 무너졌다. 예조프가 취임한 1936년 9월 체신인민위원부로 옮겨졌고 1937년 4월 체포되어 8월 총살됐으며, 복권되지 않았다.$q$,
 $q$A Kyiv-born Chekist, Prokofiev headed the OGPU Secret Department and then the Information Department before taking over the Economic Directorate in February 1926, which he ran until 1931. That branch was responsible for economic counter-intelligence, and under his direction it manufactured the great wrecking and sabotage cases against Soviet technical specialists that criminalized industrial failure. In November 1932 he became a deputy chairman of the OGPU and simultaneously took charge of the civil militia, the ordinary police, which had just been subordinated to the security organs, a consolidation that placed regular policing under Chekist control. When the NKVD was created in July 1934 he became Yagoda's second deputy commissar, one of the small group at the top of the new commissariat, and received the rank of Commissar of State Security 1st Rank in 1935. He fell with Yagoda's circle: shifted to the Communications commissariat in September 1936 as Yezhov took over, arrested in April 1937, and shot that August. He has not been rehabilitated.$q$,
