-- Role marker: all of these belong to the state-security office -------------
INSERT INTO commulingo_person_roles (person_id, icon, office_id, label_ko, label_en, updated_at)
SELECT v.id, '', 'state-security', '', '', NOW()
FROM (VALUES
    ('molchanov'), ('pauker'), ('matvei-berman'), ('balitsky'), ('georgy-prokofiev'),
    ('redens'), ('deribas'), ('evdokimov'), ('leplevsky'), ('uspensky'),
    ('belsky'), ('zhukovsky'), ('blokhin'), ('firin'), ('lazar-kogan'),
    ('frenkel'), ('goglidze'), ('dekanozov'), ('meshik'),
    ('vlodzimirsky'), ('amayak-kobulov'), ('tsanava'), ('milshtein'), ('mamulov'),
    ('rapava'), ('rukhadze'), ('shalva-tsereteli'), ('nadaraya'),
    ('karanadze'), ('savitsky'), ('khazan'), ('krimyan')
) AS v(id)
WHERE EXISTS (SELECT 1 FROM commulingo_people p WHERE p.id = v.id)
ON CONFLICT (person_id) DO UPDATE SET
    office_id = EXCLUDED.office_id, updated_at = NOW();
